const input = $input.first().json;
const plan = input.plan || input.output || input;
const errors = [];

let prepareInput = {};
try {
  prepareInput = $("Prepare Input").first().json;
} catch (error) {
  prepareInput = {};
}

const traceId = input.trace_id || prepareInput.trace_id || $execution.id;
const userQuestion = input.user_question || prepareInput.user_question || "";
const sessionId = input.session_id || prepareInput.session_id || null;
const sourceChannel = input.source_channel || prepareInput.source_channel || null;
const cacheHit = input.cache_hit === true;
const planSource = cacheHit ? "cache" : "planner";

function normalizeKey(value) {
  if (typeof value !== "string") return value;
  return value.trim().toLowerCase().replace(/\s+/g, "_");
}

function normalizePlan(rawPlan) {
  const normalized = {
    ...rawPlan,
    metrics: Array.isArray(rawPlan.metrics) ? rawPlan.metrics : [],
    dimensions: Array.isArray(rawPlan.dimensions) ? rawPlan.dimensions : [],
    filters: Array.isArray(rawPlan.filters) ? rawPlan.filters : [],
    date_range:
      rawPlan.date_range && typeof rawPlan.date_range === "object"
        ? rawPlan.date_range
        : {
            start: null,
            end: null,
            date_column: null,
            relative_period: null
          }
  };

  normalized.route = normalizeKey(normalized.route);
  normalized.dataset = normalizeKey(normalized.dataset);
  normalized.analysis_type = normalizeKey(normalized.analysis_type);
  normalized.intent = normalizeKey(normalized.intent);

  normalized.metrics = normalized.metrics.map(normalizeKey);
  normalized.dimensions = normalized.dimensions.map(normalizeKey);

  normalized.filters = normalized.filters.map(filter => ({
    ...filter,
    field: normalizeKey(filter.field),
    operator: normalizeKey(filter.operator)
  }));

  normalized.date_range = {
    start: normalized.date_range.start || null,
    end: normalized.date_range.end || null,
    date_column: normalizeKey(normalized.date_range.date_column || null),
    relative_period: normalizeKey(normalized.date_range.relative_period || null)
  };

  return normalized;
}

function baseOutput(extra) {
  return [{
    json: {
      ...input,
      trace_id: traceId,
      user_question: userQuestion,
      session_id: sessionId,
      source_channel: sourceChannel,
      cache_hit: cacheHit,
      plan_source: planSource,
      ...extra
    }
  }];
}

let normalizedPlan = normalizePlan(plan);

// Read business catalog if it is present on the current item.
// If not, fall back to the Add Business Catalog node.
let catalog = input.business_catalog || {};
if (!catalog.datasets) {
  try {
    catalog = $("Add Business Catalog").first().json.business_catalog || {};
  } catch (error) {
    catalog = {};
  }
}

const unsupportedTerms = [
  "employee",
  "employees",
  "salary",
  "salaries",
  "payroll",
  "hr",
  "human_resources",
  "inventory",
  "stock_level",
  "stock_levels",
  "support_ticket",
  "support_tickets",
  "weather",
  "stock_price",
  "stock_prices"
];

const normalizedQuestion = normalizeKey(userQuestion || "") || "";
const isClearlyUnsupported = unsupportedTerms.some(term => {
  return normalizedQuestion.includes(term);
});

// Unsupported is checked before clarification because unsupported plans often
// use dataset = unknown and analysis_type = unknown.
if (
  isClearlyUnsupported ||
  normalizedPlan.route === "unsupported" ||
  normalizedPlan.dataset === "unsupported" ||
  normalizedPlan.intent === "unsupported" ||
  normalizedPlan.analysis_type === "unsupported"
) {
  return baseOutput({
    plan_valid: false,
    route: "unsupported",
    errors: ["Unsupported dataset or question type."],
    plan: {
      ...normalizedPlan,
      route: "unsupported",
      intent: "unsupported",
      dataset: "unknown",
      analysis_type: "unknown",
      metrics: [],
      dimensions: [],
      filters: [],
      date_range: {
        start: null,
        end: null,
        date_column: "unknown",
        relative_period: null
      },
      limit: 0,
      needs_clarification: false,
      clarification_question: null
    }
  });
}

const datasets = catalog.datasets || {};
const datasetCatalog = datasets[normalizedPlan.dataset] || {};

const fieldAliases =
  datasetCatalog.field_aliases ||
  datasetCatalog.dimension_aliases ||
  {};

const metricAliases = datasetCatalog.metric_aliases || {};

const fallbackMetricAliases = {
  ecommerce_orders: {
    sales: "net_sales",
    total_sales: "net_sales",
    revenue: "net_sales",
    net_revenue: "net_sales",
    gross_revenue: "gross_sales",
    orders: "order_count",
    order_volume: "order_count",
    number_of_orders: "order_count",
    returns: "return_rate",
    returned_orders: "return_rate",
    rating: "average_rating",
    customer_rating: "average_rating",
    delivery_time: "average_delivery_days",
    shipping_time: "average_delivery_days"
  },
  marketing_campaigns: {
    return_on_ad_spend: "roas",
    return_on_ads_spend: "roas",
    roas: "roas",
    click_through_rate: "ctr",
    c_t_r: "ctr",
    cvr: "conversion_rate",
    conversion_percentage: "conversion_rate",
    conversion_percent: "conversion_rate",
    conversions_rate: "conversion_rate",
    cpc: "cost_per_click",
    cpa: "cost_per_conversion",
    cost_per_acquisition: "cost_per_conversion",
    rpc: "revenue_per_click",
    lead_customer_rate: "lead_to_customer_rate"
  }
};

const fallbackDimensionAliases = {
  ecommerce_orders: {
    category: "product_category",
    product_category_name: "product_category",
    product_type: "product_category",
    item_category: "product_category",
    product: "product_name",
    item: "product_name",
    channel: "sales_channel",
    order_channel: "sales_channel",
    purchase_channel: "sales_channel",
    platform: "sales_channel",
    payment: "payment_method",
    status: "order_status",
    location: "region",
    market: "region",
    geography: "region"
  },
  marketing_campaigns: {
    platform: "channel",
    ad_platform: "channel",
    marketing_platform: "channel",
    social_platform: "channel",
    marketing_channel: "channel",
    campaign_channel: "channel",
    traffic_channel: "channel",
    traffic_source: "channel",
    ad_channel: "channel",
    source: "channel",
    placement: "channel",
    audience: "audience_segment",
    segment: "audience_segment",
    objective: "campaign_objective",
    status: "campaign_status"
  }
};

function applyAliases(currentPlan) {
  const metricAliasMap = fallbackMetricAliases[currentPlan.dataset] || {};
  const dimensionAliasMap = fallbackDimensionAliases[currentPlan.dataset] || {};

  currentPlan.metrics = currentPlan.metrics.map(metric => {
    return metricAliases[metric] || metricAliasMap[metric] || metric;
  });

  currentPlan.dimensions = currentPlan.dimensions.map(dimension => {
    return fieldAliases[dimension] || dimensionAliasMap[dimension] || dimension;
  });

  currentPlan.filters = currentPlan.filters.map(filter => ({
    ...filter,
    field: fieldAliases[filter.field] || dimensionAliasMap[filter.field] || filter.field
  }));

  return currentPlan;
}

normalizedPlan = applyAliases(normalizedPlan);

// Phase 1 allowlist. Query builders only receive plans that pass this contract.
const allowed = {
  ecommerce_orders: {
    metrics: [
      "order_count",
      "gross_sales",
      "net_sales",
      "return_rate",
      "average_rating",
      "average_delivery_days"
    ],
    dimensions: [
      "gender",
      "region",
      "country",
      "city",
      "product_category",
      "product_name",
      "sales_channel",
      "payment_method",
      "order_status",
      "age_group"
    ],
    date_column: "order_date"
  },
  marketing_campaigns: {
    metrics: [
      "spend",
      "impressions",
      "clicks",
      "conversions",
      "revenue",
      "leads",
      "new_customers",
      "ctr",
      "conversion_rate",
      "cost_per_click",
      "cost_per_conversion",
      "roas",
      "revenue_per_click",
      "lead_to_customer_rate"
    ],
    dimensions: [
      "campaign_name",
      "channel",
      "region",
      "country",
      "audience_segment",
      "device",
      "campaign_objective",
      "campaign_status"
    ],
    date_column: "campaign_date"
  }
};

// Use metric and dimension evidence to correct obvious dataset mistakes.
const metricDatasetMap = {
  order_count: "ecommerce_orders",
  gross_sales: "ecommerce_orders",
  net_sales: "ecommerce_orders",
  return_rate: "ecommerce_orders",
  average_rating: "ecommerce_orders",
  average_delivery_days: "ecommerce_orders",
  spend: "marketing_campaigns",
  impressions: "marketing_campaigns",
  clicks: "marketing_campaigns",
  conversions: "marketing_campaigns",
  revenue: "marketing_campaigns",
  leads: "marketing_campaigns",
  new_customers: "marketing_campaigns",
  ctr: "marketing_campaigns",
  conversion_rate: "marketing_campaigns",
  cost_per_click: "marketing_campaigns",
  cost_per_conversion: "marketing_campaigns",
  roas: "marketing_campaigns",
  revenue_per_click: "marketing_campaigns",
  lead_to_customer_rate: "marketing_campaigns"
};

const dimensionDatasetMap = {
  product_category: "ecommerce_orders",
  product_name: "ecommerce_orders",
  sales_channel: "ecommerce_orders",
  payment_method: "ecommerce_orders",
  order_status: "ecommerce_orders",
  age_group: "ecommerce_orders",
  channel: "marketing_campaigns",
  audience_segment: "marketing_campaigns",
  device: "marketing_campaigns",
  campaign_objective: "marketing_campaigns",
  campaign_status: "marketing_campaigns",
  campaign_name: "marketing_campaigns"
};

const datasetVotes = normalizedPlan.metrics
  .map(metric => metricDatasetMap[metric])
  .concat(normalizedPlan.dimensions.map(dimension => dimensionDatasetMap[dimension]))
  .filter(Boolean);

const ecommerceVotes = datasetVotes.filter(dataset => dataset === "ecommerce_orders").length;
const marketingVotes = datasetVotes.filter(dataset => dataset === "marketing_campaigns").length;

if (marketingVotes > ecommerceVotes) {
  normalizedPlan.dataset = "marketing_campaigns";
  normalizedPlan.date_range.date_column = "campaign_date";
  normalizedPlan = applyAliases(normalizedPlan);
}

if (ecommerceVotes > marketingVotes) {
  normalizedPlan.dataset = "ecommerce_orders";
  normalizedPlan.date_range.date_column = "order_date";
  normalizedPlan = applyAliases(normalizedPlan);
}

// Clarification is for vague but potentially supported questions.
if (
  normalizedPlan.route === "clarification" ||
  normalizedPlan.needs_clarification === true ||
  normalizedPlan.dataset === "unknown" ||
  normalizedPlan.analysis_type === "unknown"
) {
  return baseOutput({
    plan_valid: false,
    route: "clarification",
    errors: [],
    plan: normalizedPlan
  });
}

const datasetConfig = allowed[normalizedPlan.dataset];

if (!datasetConfig) {
  errors.push(`Invalid dataset: ${normalizedPlan.dataset}`);
}

if (
  datasetConfig &&
  (!normalizedPlan.date_range.date_column ||
    normalizedPlan.date_range.date_column === "unknown")
) {
  normalizedPlan.date_range.date_column = datasetConfig.date_column;
}

// If the Planner supplied filters but forgot dimensions, infer dimensions from
// valid filter fields. Example: product_category = Electronics.
if (datasetConfig) {
  for (const filter of normalizedPlan.filters) {
    if (
      datasetConfig.dimensions.includes(filter.field) &&
      !normalizedPlan.dimensions.includes(filter.field)
    ) {
      normalizedPlan.dimensions.push(filter.field);
    }
  }
}

for (const metric of normalizedPlan.metrics) {
  if (datasetConfig && !datasetConfig.metrics.includes(metric)) {
    errors.push(`Metric "${metric}" is not allowed for ${normalizedPlan.dataset}`);
  }
}

for (const dimension of normalizedPlan.dimensions) {
  if (datasetConfig && !datasetConfig.dimensions.includes(dimension)) {
    errors.push(`Dimension "${dimension}" is not allowed for ${normalizedPlan.dataset}`);
  }
}

if (
  datasetConfig &&
  normalizedPlan.date_range.date_column &&
  normalizedPlan.date_range.date_column !== datasetConfig.date_column
) {
  errors.push(`Invalid date column for ${normalizedPlan.dataset}`);
}

const dimensionRequiredTypes = [
  "grouped_metric_ranking",
  "grouped_metric_breakdown",
  "filtered_grouped_breakdown",
  "dimension_comparison"
];

if (
  dimensionRequiredTypes.includes(normalizedPlan.analysis_type) &&
  normalizedPlan.dimensions.length === 0
) {
  errors.push(
    `Analysis type "${normalizedPlan.analysis_type}" requires at least one dimension.`
  );
}

return baseOutput({
  plan_valid: errors.length === 0,
  route: errors.length === 0 ? normalizedPlan.dataset : "invalid_plan",
  errors,
  plan: normalizedPlan
});

