const input = $input.first().json;

const route = input.route || (input.output ? input.output.route : null);
const plan = input.plan || input.output || {};
const errors = input.errors || [];
const warnings = input.warnings || [];

const traceId = input.trace_id || $execution.id;
const userQuestion = input.user_question || "";
const sessionId = input.session_id || null;
const sourceChannel = input.source_channel || null;

let response = "";

if (route === "security_blocked") {
  response =
    input.response ||
    "I cannot process this request because it did not pass the workflow safety checks.";
} else if (route === "clarification") {
  response =
    plan.clarification_question ||
    "Can you clarify what you would like me to analyze?";
} else if (route === "unsupported") {
  response =
    "I’m built specifically for ecommerce and marketing analytics. This question looks outside the datasets currently available.";
} else if (route === "invalid_plan") {
  response =
    "I could not create a safe analysis plan for this question. Please ask using a supported ecommerce or marketing metric, such as sales by category, return rate by region, or ROAS by channel.";
} else {
  response =
    "I could not route this request safely. Please try a supported ecommerce or marketing analytics question.";
}

return [{
  json: {
    trace_id: traceId,
    user_question: userQuestion,
    session_id: sessionId,
    source_channel: sourceChannel,
    status: route || "controlled_failure",
    response,
    route,
    plan,
    errors,
    warnings,
    security_signals: input.security_signals || [],
    selected_dataset: input.selected_dataset || input.dataset || plan.dataset || "unknown",
    dataset: input.dataset || plan.dataset || "unknown",
    metrics: input.metrics || plan.metrics || [],
    analysis_type: input.analysis_type || plan.analysis_type || "unknown",
    row_count: input.row_count || 0,
    date_start: input.date_start || null,
    date_end: input.date_end || null,
    response_type: "controlled_failure"
  }
}];

const cleanDate = (value) => {
  if (value === undefined || value === null) return null;
  if (typeof value === "string") {
    const trimmed = value.trim().toLowerCase();
    if (trimmed === "" || trimmed === "null" || trimmed === "unknown") return null;
  }
  return value;
};

const metrics = Array.isArray($json.metrics)
  ? $json.metrics
  : Array.isArray($json.plan?.metrics)
    ? $json.plan.metrics
    : $json.metric
      ? [$json.metric]
      : $json.metric_key
        ? [$json.metric_key]
        : [];

return [{
  json: {
    ...$json,
    selected_dataset: $json.dataset || $json.plan?.dataset || "unknown",
    metrics,
    date_start: cleanDate($json.date_start),
    date_end: cleanDate($json.date_end),
    warnings: Array.isArray($json.warnings) ? $json.warnings : []
  }
}];

const prepareInput = $("Prepare Input").first().json;

// Adjust this depending on where your Supabase cache row stores the plan.
// Common possibilities: $json.plan, $json.cached_plan, $json.plan_json
const rawCachedPlan =
  $json.plan ||
  $json.cached_plan ||
  $json.plan_json ||
  $json.output ||
  null;

let plan = rawCachedPlan;

try {
  if (typeof plan === "string") {
    plan = JSON.parse(plan);
  }
} catch (error) {
  plan = null;
}

if (plan && plan.plan) {
  plan = plan.plan;
}

if (!plan || typeof plan !== "object") {
  return [{
    json: {
      ...prepareInput,
      plan_valid: false,
      route: "invalid_plan",
      errors: ["Cache hit did not include a usable analysis plan."],
      cache_hit: true,
      plan_source: "cache",
      plan: null
    }
  }];
}

const route =
  plan.route === "unsupported"
    ? "unsupported"
    : plan.needs_clarification
      ? "clarification"
      : plan.dataset || "invalid_plan";

return [{
  json: {
    ...prepareInput,
    plan_valid: route !== "invalid_plan",
    route,
    errors: [],
    cache_hit: true,
    plan_source: "cache",
    plan
  }
}];

const question = ($json.user_question || "").trim();

const normalizedQuestion = question
  .toLowerCase()
  .replace(/[^\w\s]/g, "")
  .replace(/\s+/g, " ")
  .trim();

let catalog = $json.business_catalog || {};

if (typeof catalog === "string") {
  try {
    catalog = JSON.parse(catalog);
  } catch (error) {
    catalog = {};
  }
}

const catalogVersion = catalog.catalog_version || "unknown_catalog";
const questionHash = `${catalogVersion}:${normalizedQuestion}`;

return [{
  json: {
    ...$json,
    business_catalog: catalog,
    normalized_question: normalizedQuestion,
    catalog_version: catalogVersion,
    question_hash: questionHash
  }
}];

const original = $("Normalize Question For Cache").first().json;

return [{
  json: {
    ...original,

    cache_hit: $json.cache_hit === true,
    cached_plan: $json.plan || null,
    cached_route: $json.route || null,
    cached_dataset: $json.dataset || null,
    cached_analysis_type: $json.analysis_type || null,
    cached_metrics: Array.isArray($json.metrics) ? $json.metrics : [],
    cached_dimensions: Array.isArray($json.dimensions) ? $json.dimensions : [],
    cached_hit_count: Number($json.hit_count || 0)
  }
}];

const validatedPlanPayload = $("Validate Analysis Plan").first().json;

return [{
  json: {
    ...validatedPlanPayload,
    cache_saved: true
  }
}];

const input = $input.first().json;
const plan = input.plan || {};

if (!plan.date_range || typeof plan.date_range !== "object") {
  plan.date_range = {
    start: null,
    end: null,
    date_column: null,
    relative_period: null
  };
}

const relativePeriod = plan.date_range.relative_period || null;
const question = String(input.user_question || "").toLowerCase();

// n8n runs on the server timezone, so use UTC-safe date construction.
// This prevents off-by-one date bugs when formatting YYYY-MM-DD.
const today = new Date();

const toDateOnly = (date) => date.toISOString().slice(0, 10);

const makeDate = (year, monthIndex, day) => {
  return new Date(Date.UTC(year, monthIndex, day));
};

const startOfMonth = (date) => {
  return makeDate(date.getUTCFullYear(), date.getUTCMonth(), 1);
};

const endOfMonth = (date) => {
  return makeDate(date.getUTCFullYear(), date.getUTCMonth() + 1, 0);
};

const startOfYear = (date) => {
  return makeDate(date.getUTCFullYear(), 0, 1);
};

const endOfYear = (date) => {
  return makeDate(date.getUTCFullYear(), 11, 31);
};

const startOfQuarter = (date) => {
  const quarterStartMonth = Math.floor(date.getUTCMonth() / 3) * 3;
  return makeDate(date.getUTCFullYear(), quarterStartMonth, 1);
};

const endOfQuarter = (date) => {
  const quarterStartMonth = Math.floor(date.getUTCMonth() / 3) * 3;
  return makeDate(date.getUTCFullYear(), quarterStartMonth + 3, 0);
};

let start = plan.date_range.start || null;
let end = plan.date_range.end || null;
let dateLabel = null;

// Only resolve relative dates when the planner has not already provided
// explicit start/end dates.
if (!start && !end) {
  if (
    relativePeriod === "last_month" ||
    question.includes("last month") ||
    question.includes("previous month")
  ) {
    const reference = makeDate(today.getUTCFullYear(), today.getUTCMonth() - 1, 1);
    start = toDateOnly(startOfMonth(reference));
    end = toDateOnly(endOfMonth(reference));
    dateLabel = "last_month";
  } else if (
    relativePeriod === "this_month" ||
    question.includes("this month")
  ) {
    start = toDateOnly(startOfMonth(today));
    end = toDateOnly(today);
    dateLabel = "this_month";
  } else if (
    relativePeriod === "last_year" ||
    question.includes("last year") ||
    question.includes("previous year")
  ) {
    const reference = makeDate(today.getUTCFullYear() - 1, 0, 1);
    start = toDateOnly(startOfYear(reference));
    end = toDateOnly(endOfYear(reference));
    dateLabel = "last_year";
  } else if (
    relativePeriod === "this_year" ||
    question.includes("this year")
  ) {
    start = toDateOnly(startOfYear(today));
    end = toDateOnly(today);
    dateLabel = "this_year";
  } else if (
    relativePeriod === "last_quarter" ||
    question.includes("last quarter") ||
    question.includes("previous quarter")
  ) {
    const currentQuarterStart = startOfQuarter(today);
    const reference = makeDate(
      currentQuarterStart.getUTCFullYear(),
      currentQuarterStart.getUTCMonth() - 1,
      1
    );
    start = toDateOnly(startOfQuarter(reference));
    end = toDateOnly(endOfQuarter(reference));
    dateLabel = "last_quarter";
  } else if (
    relativePeriod === "this_quarter" ||
    question.includes("this quarter")
  ) {
    start = toDateOnly(startOfQuarter(today));
    end = toDateOnly(today);
    dateLabel = "this_quarter";
  } else if (
    relativePeriod === "year_to_date" ||
    question.includes("year to date") ||
    question.includes("ytd")
  ) {
    start = toDateOnly(startOfYear(today));
    end = toDateOnly(today);
    dateLabel = "year_to_date";
  }
}

plan.date_range.start = start;
plan.date_range.end = end;

return [{
  json: {
    ...input,
    plan,
    date_resolution: {
      resolved: Boolean(start && end),
      label: dateLabel,
      start,
      end,
      date_column: plan.date_range.date_column || null
    }
  }
}];

const input = $input.first().json;
const cachePlan = JSON.parse(JSON.stringify(input.plan || {}));

if (!cachePlan.date_range || typeof cachePlan.date_range !== "object") {
  cachePlan.date_range = {
    start: null,
    end: null,
    date_column: null,
    relative_period: null
  };
}

if (cachePlan.date_range.relative_period) {
  cachePlan.date_range.start = null;
  cachePlan.date_range.end = null;
}

return [{
  json: {
    ...input,
    cache_plan: cachePlan
  }
}];

// Build a deterministic SQL query from:
// 1. the validated analysis plan
// 2. dataset_metadata
// 3. metric_registry metric definition
//
// The LLM does not write SQL. It only provides a structured plan.
// This node turns that plan into an allowlisted SQL template.

const input = $input.first().json;
const prepareInput = $("Prepare Input").first().json;

const plan = input.plan || {};
const datasetMetadata = input.dataset_metadata || {};
const metricDefinition = input.metric_definition || {};

const dataset = plan.dataset;
const analysisType = plan.analysis_type;
const metrics = Array.isArray(plan.metrics) ? plan.metrics : [];
const dimensions = Array.isArray(plan.dimensions) ? plan.dimensions : [];
const filters = Array.isArray(plan.filters) ? plan.filters : [];
const limit = Number(plan.limit || 0);

function fail(message) {
  return [{
    json: {
      ...input,
      route: "invalid_plan",
      query_status: "failed",
      errors: [...(input.errors || []), message]
    }
  }];
}

function sqlString(value) {
  return String(value).replace(/'/g, "''");
}

function isSafeIdentifier(value) {
  return typeof value === "string" && /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(value);
}

// Required context checks.
if (!dataset) {
  return fail("No dataset was provided.");
}

if (!datasetMetadata.dataset_name) {
  return fail(`No dataset metadata was found for ${dataset}.`);
}

if (datasetMetadata.dataset_name !== dataset) {
  return fail(
