  const whereParts = [];

  if (requiresDimensionFilter && relevantFilters.length) {
    const values = relevantFilters.map(filter => `'${sqlString(filter.value)}'`);

    if (values.length === 1) {
      whereParts.push(`${dimensionSql} = ${values[0]}`);
    } else {
      whereParts.push(`${dimensionSql} IN (${values.join(", ")})`);
    }
  }

  if (plan.date_range && plan.date_range.start && plan.date_range.end) {
    whereParts.push(
      `${dateColumn} BETWEEN '${sqlString(plan.date_range.start)}'::date AND '${sqlString(plan.date_range.end)}'::date`
    );
  }

  return whereParts.length ? `WHERE ${whereParts.join(" AND ")}` : "";
}

