  SELECT *
  FROM ${table}
  ${whereClause}
),
grouped AS (
  SELECT
    ${dimensionSql} AS dimension_value,
    COUNT(*) AS group_record_count,
    ROUND((${metricSql})::numeric, 2) AS metric_value
  FROM base
  GROUP BY ${dimensionSql}
),
metadata AS (
  SELECT
    COUNT(*) AS total_row_count,
    MIN(${dateColumn})::text AS date_start,
    MAX(${dateColumn})::text AS date_end
  FROM base
),
final_rows AS (
