    '${dataset}' AS dataset,
    '${analysisType}' AS analysis_type,
    '${metric}' AS metric,
    '${dimension}' AS primary_dimension,
    grouped.dimension_value,
    grouped.group_record_count,
    metadata.total_row_count,
    metadata.date_start,
    metadata.date_end,
    grouped.metric_value
  FROM grouped
  CROSS JOIN metadata

  UNION ALL

  SELECT
    '${dataset}' AS dataset,
    '${analysisType}' AS analysis_type,
    '${metric}' AS metric,
    '${dimension}' AS primary_dimension,
    NULL AS dimension_value,
    0 AS group_record_count,
    metadata.total_row_count,
    metadata.date_start,
    metadata.date_end,
    NULL AS metric_value
  FROM metadata
  WHERE NOT EXISTS (SELECT 1 FROM grouped)
)
SELECT *
FROM final_rows
ORDER BY metric_value ${sortDirection} NULLS LAST
${limitClause};
`;

